import { doc, getDoc, updateDoc, onSnapshot, setDoc, collection, getDocs } from 'firebase/firestore';
import { db, auth, Consultation } from './firebase';
import { createGoogleCalendarEvent } from './googleMeetClient';

/**
 * Detects whether a Google Meet link is a fake, synthetic fallback link.
 * Real Google Meet codes generated by Google are strictly lowercase letters in format [a-z]{3}-[a-z]{4}-[a-z]{3}.
 * Fake fallback links:
 * - Contain numbers (0-9) because they were constructed from Firestore doc IDs.
 * - Contain padding 'x' characters (e.g. 'xxxx' or 'dlb-cxxx-xxxx').
 * - Match the synthetic derivation from the appointment ID.
 */
export function isSyntheticMeetUrl(url?: string | null, appointmentId?: string): boolean {
  if (!url) return false;

  const trimmed = url.trim().toLowerCase();

  let parsedUrl: URL;
  try {
    parsedUrl = new URL(trimmed);
  } catch {
    return false;
  }

  if (parsedUrl.protocol !== 'https:' || parsedUrl.host !== 'meet.google.com') {
    return false;
  }

  const match = parsedUrl.pathname.match(/^\/([a-z0-9-]+)/);
  if (!match) return false;

  const code = match[1].replace(/-/g, '');

  // Real Google Meet codes are 10 letters (e.g. abc-defg-hij). 'new' or short codes are not valid meeting rooms
  if (code === 'new' || code.length < 9) {
    return true;
  }

  // Real Google Meet codes never contain digits
  if (/\d/.test(code)) {
    return true;
  }

  // Real Google Meet codes don't have multiple consecutive 'x' characters from .padEnd(10, 'x')
  if (code.includes('xxxx') || code.includes('xxx') || code.endsWith('xx')) {
    return true;
  }

  // Known fallback keywords
  if (code.includes('dlbc') || code.includes('session')) {
    return true;
  }

  // Check against the deterministic algorithm
  if (appointmentId) {
    const safeId = appointmentId.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 10);
    const safeWithPadding = safeId.padEnd(10, 'x');
    const syntheticCode = `${safeWithPadding.slice(0, 3)}-${safeWithPadding.slice(3, 7)}-${safeWithPadding.slice(7, 10)}`;
    if (trimmed.includes(syntheticCode.toLowerCase())) {
      return true;
    }
  }

  return false;
}

/**
 * Cleans up corrupted synthetic/fake meeting links from Firestore documents.
 */
export async function cleanupSyntheticMeetLinksInFirestore(): Promise<number> {
  let cleanedCount = 0;
  try {
    const consultationsRef = collection(db, 'consultations');
    const snapshot = await getDocs(consultationsRef);
    for (const docSnap of snapshot.docs) {
      const data = docSnap.data();
      const existingUrl = data.meetUrl || data.googleMeetUrl || data.meetingLink;
      if (existingUrl && isSyntheticMeetUrl(existingUrl, docSnap.id)) {
        console.warn(`[Cleanup] Removing corrupted synthetic meet link from consultation ${docSnap.id}: ${existingUrl}`);
        await updateDoc(docSnap.ref, {
          meetUrl: null,
          googleMeetUrl: null,
          meetingLink: null,
          meetingLinkStatus: 'pending',
          updatedAt: new Date().toISOString()
        });
        cleanedCount++;
      }
    }
  } catch (err) {
    console.error('Error during synthetic meet links cleanup:', err);
  }
  return cleanedCount;
}

export interface InitializeMeetingOptions {
  summary?: string;
  description?: string;
  startIso?: string;
  endIso?: string;
  durationMinutes?: number;
  accessToken?: string | null;
  memberEmail?: string;
  leaderEmail?: string;
  method?: 'google_meet' | 'zoom' | 'in_person';
  isTestAccess?: boolean;
}

/**
 * Creates a standalone instant Google Meet test room
 */
export async function createInstantTestMeetRoom(options?: {
  accessToken?: string | null;
  userDisplayName?: string;
}): Promise<string> {
  // First attempt backend test room creation
  try {
    const res = await fetch('/api/consultations/create-test-meeting', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        accessToken: options?.accessToken || null,
        userDisplayName: options?.userDisplayName || 'User'
      }),
    });

    if (res.ok) {
      const text = await res.text();
      let data: any = null;
      try { data = JSON.parse(text); } catch {}
      if (data?.meetUrl && !isSyntheticMeetUrl(data.meetUrl, 'test')) {
        return data.meetUrl;
      }
    }
  } catch (err) {
    console.warn('Backend create-test-meeting failed, attempting client fallback:', err);
  }

  // Client-side fallback if accessToken exists
  if (options?.accessToken) {
    const startIso = new Date().toISOString();
    const endIso = new Date(Date.now() + 45 * 60000).toISOString();
    const calResult = await createGoogleCalendarEvent({
      summary: `DLBC Google Meet Test — ${options.userDisplayName || 'Pastor/Member'}`,
      description: 'Temporary meeting room to verify Google Meet setup and connectivity.',
      startIso,
      endIso,
      accessToken: options.accessToken,
    });
    if (calResult?.hangoutLink && !isSyntheticMeetUrl(calResult.hangoutLink, 'test')) {
      return calResult.hangoutLink;
    }
  }

  throw new Error('Unable to create test meeting room. Please ensure Google permissions are authorized.');
}

/**
 * Idempotent Read-First Meet URL retrieval and persistence.
 * Checks Firestore document first. If meetUrl already exists, returns it.
 * If missing, attempts generation via backend or client OAuth and persists ONLY genuine URLs.
 */
export async function getOrInitializeMeetUrl(
  appointmentId: string,
  options?: InitializeMeetingOptions
): Promise<string> {
  if (!appointmentId) {
    throw new Error('Appointment ID is required to resolve meeting link.');
  }

  // 1. READ-FIRST PATTERN: Check if valid meetUrl already exists in Firestore
  const consultationRef = doc(db, 'consultations', appointmentId);
  const snap = await getDoc(consultationRef);

  let existingData: any = null;
  if (snap.exists()) {
    existingData = snap.data();
    const existingMeetUrl = existingData.meetUrl || existingData.googleMeetUrl || existingData.meetingLink || existingData.meeting?.url;
    if (existingMeetUrl && typeof existingMeetUrl === 'string' && existingMeetUrl.trim().length > 0) {
      return existingMeetUrl.trim();
    }
  }

  if (existingData?.meetingMethod === 'in_person' || options?.method === 'in_person') {
    return '';
  }

  let newMeetUrl: string | null = null;
  let newEventId: string | null = null;

  // 2. BACKEND GENERATION: Call server endpoint
  try {
    const idToken = await auth.currentUser?.getIdToken();
    const res = await fetch('/api/consultations/join', {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        ...(idToken ? { Authorization: `Bearer ${idToken}` } : {}),
      },
      body: JSON.stringify({ 
        consultationId: appointmentId,
        accessToken: options?.accessToken || null,
        isTestAccess: options?.isTestAccess || false
      }),
    });

    const resText = await res.text();
    let resData: any = null;
    try { resData = JSON.parse(resText); } catch {}

    if (res.ok && resData) {
      const rawUrl = resData.meetUrl || resData.meetingLink || resData.googleMeetUrl || resData.url || null;
      if (rawUrl && !isSyntheticMeetUrl(rawUrl, appointmentId)) {
        newMeetUrl = rawUrl;
        newEventId = resData.eventId || resData.calendarEventId || null;
      } else if (rawUrl) {
        console.warn('Backend returned synthetic meet link, discarding:', rawUrl);
      }
    } else {
      if (resData?.error) {
        if (resData.error.includes('Room is locked') || resData.error.includes('expired') || resData.error.includes('in-person')) {
          throw new Error(resData.error);
        }
      }
      console.warn('Backend meeting creation responded with:', res.status, resData?.error || resText);
    }
  } catch (err: any) {
    if (err.message?.includes('Room is locked') || err.message?.includes('expired') || err.message?.includes('in-person')) {
      throw err;
    }
    console.warn('Backend join attempt completed with fallback:', err?.message || err);
  }

  // 3. CLIENT-SIDE FALLBACK: Use Google Calendar API if backend failed and access token is present
  if (!newMeetUrl && options?.accessToken) {
    try {
      const startIso = options?.startIso || existingData?.scheduledStart || existingData?.selectedTime || new Date().toISOString();
      const durationMinutes = options?.durationMinutes || 45;
      const endIso = options?.endIso || existingData?.scheduledEnd || new Date(new Date(startIso).getTime() + durationMinutes * 60000).toISOString();

      const calResult = await createGoogleCalendarEvent({
        summary: options?.summary || `DLBC Consultation — ${existingData?.category || 'Pastoral Care'}`,
        description: options?.description || `Consultation ID: ${appointmentId}\nConfidential pastoral care session.`,
        startIso,
        endIso,
        accessToken: options.accessToken,
      });

      if (calResult?.hangoutLink && !isSyntheticMeetUrl(calResult.hangoutLink, appointmentId)) {
        newMeetUrl = calResult.hangoutLink;
        newEventId = calResult.id || null;
      }
    } catch (clientErr) {
      console.error('Client Google Calendar API generation failed:', clientErr);
    }
  }

  // 4. GUARD: Fail gracefully if no valid meeting URL could be generated
  if (!newMeetUrl) {
    throw new Error('Failed to generate a valid Google Meet link. Please check Google API permissions or access token.');
  }

  // 5. PERSISTENCE: Save ONLY valid, generated meeting URLs to Firestore
  const updatePayload: Record<string, any> = {
    meetUrl: newMeetUrl,
    googleMeetUrl: newMeetUrl,
    meetingLink: newMeetUrl,
    meetingLinkStatus: 'active',
    updatedAt: new Date().toISOString(),
  };

  if (newEventId) {
    updatePayload.calendarEventId = newEventId;
    updatePayload.googleEventId = newEventId;
  }

  if (snap.exists()) {
    await updateDoc(consultationRef, updatePayload);
  } else {
    const appointmentRef = doc(db, 'appointments', appointmentId);
    await setDoc(appointmentRef, updatePayload, { merge: true });
  }

  return newMeetUrl;
}

/**
 * Subscribe to real-time updates for a single consultation/appointment.
 */
export function subscribeToAppointment(
  appointmentId: string,
  onUpdate: (consultation: Consultation | null) => void,
  onError?: (error: Error) => void
): () => void {
  const docRef = doc(db, 'consultations', appointmentId);
  return onSnapshot(
    docRef,
    (snap) => {
      if (snap.exists()) {
        onUpdate({ id: snap.id, ...snap.data() } as Consultation);
      } else {
        onUpdate(null);
      }
    },
    (err) => {
      console.error(`Error in appointment subscription (${appointmentId}):`, err);
      if (onError) onError(err);
    }
  );
}
